"""Regression checks for the aiogram runtime generated by Simple Builder."""
import ast
from io import BytesIO
from zipfile import ZipFile

from fastapi import FastAPI
from fastapi.testclient import TestClient

from api.simple_builder import router


app = FastAPI()
app.include_router(router)
client = TestClient(app)

SCENARIO = {
    "name": "Group chat demo",
    "start": "welcome",
    "nodes": [
        {"id": "welcome", "kind": "choice", "text": "Choose", "options": [
            {"label": "One", "target": "finish"},
            {"label": "Two", "target": "finish"},
        ]},
        {"id": "finish", "kind": "end", "text": "Done"},
    ],
}


def test_generated_runtime_uses_per_user_cursor_and_bounded_index():
    result = client.post("/api/v1/builder/simple/export", json=SCENARIO)
    assert result.status_code == 200
    with ZipFile(BytesIO(result.content)) as archive:
        source = archive.read("bot.py").decode("utf-8")
    ast.parse(source)
    assert "CURSORS: dict[tuple[int, int], str]" in source
    assert "CURSORS.get(cursor_key)" in source
    assert "call.from_user.id" in source
    assert "not number.isdecimal()" in source
    assert 'index >= len(node["options"])' in source
    assert "node[\"options\"][-1]" not in source


def test_export_keeps_both_choice_options():
    result = client.post("/api/v1/builder/simple/export", json=SCENARIO)
    assert result.status_code == 200
    with ZipFile(BytesIO(result.content)) as archive:
        import json
        data = json.loads(archive.read("scenario.json"))
    assert len(data["nodes"][0]["options"]) == 2
